/* Hidden state guarantee */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --border-color: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-color: #38bdf8;
  --error-color: #f87171;
  --error-bg: rgba(248, 113, 113, 0.12);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.converter-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 440px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.card-header {
  text-align: center;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 6px;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.preview-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
}

.color-swatch {
  width: 100%;
  height: 96px;
  border-radius: 12px;
  border: 2px solid var(--border-color);
  background-color: #000000;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.hex-container {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 6px 14px;
  background-color: rgba(15, 23, 42, 0.6);
  border-radius: 8px;
  border: 1px solid var(--border-color);
}

.hex-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.05em;
}

.hex-value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.05em;
}

.controls-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-main);
}

.color-input {
  font-size: 1rem;
  padding: 10px 14px;
  background-color: #0f172a;
  color: var(--text-main);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.color-input:hover {
  border-color: #475569;
}

.color-input:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.color-input:active {
  background-color: #0c1322;
}

.error-message {
  color: var(--error-color);
  background-color: var(--error-bg);
  border: 1px solid var(--error-color);
  padding: 10px 14px;
  border-radius: 8px;
  font-weight: 600;
  text-align: center;
  font-size: 0.95rem;
}

document.addEventListener('DOMContentLoaded', () => {
  const redInput = document.getElementById('redInput');
  const greenInput = document.getElementById('greenInput');
  const blueInput = document.getElementById('blueInput');
  const colorSwatch = document.getElementById('colorSwatch');
  const hexValue = document.getElementById('hexValue');
  const errorMessage = document.getElementById('errorMessage');

  function isValidRgbComponent(valStr) {
    if (valStr.trim() === '') {
      return false;
    }
    const num = Number(valStr);
    return Number.isInteger(num) && num >= 0 && num <= 255;
  }

  function toHex(val) {
    const hex = Number(val).toString(16).toUpperCase();
    return hex.length === 1 ? '0' + hex : hex;
  }

  function updateColor() {
    const rVal = redInput.value;
    const gVal = greenInput.value;
    const bVal = blueInput.value;

    const isValid = isValidRgbComponent(rVal) && isValidRgbComponent(gVal) && isValidRgbComponent(bVal);

    if (isValid) {
      errorMessage.hidden = true;
      const r = Number(rVal);
      const g = Number(gVal);
      const b = Number(bVal);

      const hex = `#${toHex(r)}${toHex(g)}${toHex(b)}`;
      hexValue.textContent = hex;
      colorSwatch.style.backgroundColor = `rgb(${r}, ${g}, ${b})`;
    } else {
      errorMessage.hidden = false;
      hexValue.textContent = 'Invalid value';
      colorSwatch.style.backgroundColor = 'transparent';
    }
  }

  const inputs = [redInput, greenInput, blueInput];
  inputs.forEach((input) => {
    input.addEventListener('input', updateColor);
  });

  // Initial render
  updateColor();
});
